mods.body:
#siteNotice,
.cn-fundraising,
.central-notice,
.top-banner,
.rst-versions {
  display: none !important;
}
#mw-content-text p,
article p {
  line-height: 1.75 !important;
}

(() => {
  const blocks = document.querySelectorAll('pre');
  for (const pre of blocks) {
    if (pre.dataset.pcCopyDone || pre.querySelector('button')) continue;
    if ((pre.textContent || '').trim().length < 16) continue;
    pre.dataset.pcCopyDone = '1';
    if (getComputedStyle(pre).position === 'static') pre.style.position = 'relative';
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = 'Copy';
    btn.style.cssText = 'position:absolute;top:6px;right:6px;z-index:5;padding:2px 8px;border-radius:5px;border:1px solid rgba(128,128,128,.35);background:rgba(28,25,23,.85);color:#FAF8F5;font:500 11px/1.4 ui-monospace,monospace;cursor:pointer';
    btn.addEventListener('click', () => {
      const codeEl = pre.querySelector('code') || pre;
      navigator.clipboard.writeText((codeEl.innerText || '').trim()).then(() => {
        btn.textContent = 'Copied';
        setTimeout(() => { btn.textContent = 'Copy'; }, 1200);
      }).catch(() => {});
    });
    pre.appendChild(btn);
  }
})();

